script:
(function () {
  'use strict';
  // Payment-option ARM (option ARM) with negative amortization, month by month.
  //   Accrual rate: the start rate for the first `teaser` months, then the fully indexed rate
  //   (index + margin), changed by the expected change once a year and held between 0 and the
  //   lifetime cap. Interest each month = balance x rate / 12 (rounded to the cent).
  //   Minimum payment: fully amortizing at the start rate over the term; every 12 months it is
  //   reset to the fully amortizing payment at the current rate on the current balance, but may
  //   not rise by more than the payment cap (e.g. 7.5%) over the previous minimum.
  //   Paying less than the interest adds the difference to the balance (deferred interest).
  //   Recast: if the balance would pass the negative-amortization cap (e.g. 115% of the original
  //   loan) or the scheduled recast date arrives (e.g. after 5 years), the payment becomes fully
  //   amortizing over the remaining term with no payment cap, recalculated whenever the rate moves.
  //   Interest-only option: interest each month until the scheduled recast, then fully amortizing.
  //   Fully amortizing option: the level payment at the current rate over the remaining term.
  //   Payment = rB / (1 - (1 + r)^-n) (B / n at 0%); the last payment clears the balance.
  // Verified (scratchpad b7opt/tests/oa.test.js, oa_ref.py):
  //   $200,000 at 6% for 30 years -> $1,199.10 (standard table value); $400,000 at 1.5% over 360
  //   months -> $1,380.48 first minimum; by hand: balances $399,119.52, $398,237.94, $397,355.26
  //   after months 1-3, month-4 interest at 7% = $2,317.91 so $937.43 is deferred; year-2 minimum
  //   = $1,380.48 x 1.075 = $1,484.02 (payment cap binds); the recast payment equals the
  //   closed-form amortizing payment on the balance and months left at recast; the balance never
  //   passes the cap. Defaults (7%, 110% cap, 5-year recast): cap reached in month 53, payment
  //   $1,843.59 -> $3,078.83, peak $439,805.50; 6.5% / 115% / 5 years -> scheduled recast in
  //   month 61, $1,843.59 -> $2,930.54, total interest $575,381.05 (interest-only $535,247.95);
  //   6.5% + 0.5 pt a year / 125% / 10 years -> cap in month 86, $2,290.29 -> $4,608.90. All match
  //   a separate Decimal (half-up cents) Python implementation of the same rules to the cent;
  //   0% rates give level principal-only payments with no NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function cents(x) { return Math.round(x * 100) / 100; }
  function amortPay(balance, annualRate, months) {
    if (months <= 0) return balance;
    var r = annualRate / 12;
    return cents(r === 0 ? balance / months : r * balance / (1 - Math.pow(1 + r, -months)));
  }

  function rateFor(m, o) {
    if (m <= o.teaser) return o.start;
    var yearsIn = Math.floor((m - 1) / 12);
    return Math.min(o.lifeCap, Math.max(0, o.fir + o.change * yearsIn));
  }

  // mode: 'min' | 'io' | 'full'
  function simulate(o, mode) {
    var N = o.term * 12, bal = o.amount, capBal = o.amount * o.negCap, recastAt = o.recastYears * 12;
    var minPay = amortPay(o.amount, o.start, N), firstPay = 0;
    var recast = false, reason = '', recastMonth = 0, prePay = 0, postPay = 0;
    var months = [], peak = bal, deferredTotal = 0, interestTotal = 0, paidTotal = 0, maxPay = 0;
    var lastRate = -1, levelPay = 0;
    for (var m = 1; m <= N; m++) {
      var rate = rateFor(m, o), remaining = N - m + 1, pay;
      var interest = cents(bal * rate / 12);
      if (mode === 'full') {
        if (rate !== lastRate || m === 1) levelPay = amortPay(bal, rate, remaining);
        pay = levelPay;
      } else {
        if (!recast && m > 1 && (m - 1) % 12 === 0 && mode === 'min') {
          var target = amortPay(bal, rate, remaining);
          minPay = Math.min(target, cents(minPay * (1 + o.payCap)));
          if (target < minPay) minPay = target;
        }
        if (!recast && m === recastAt + 1) { recast = true; reason = 'scheduled'; recastMonth = m; }
        if (!recast && mode === 'min' && bal + interest - minPay > capBal + 0.005) { recast = true; reason = 'cap'; recastMonth = m; }
        if (recast) {
          if (m === recastMonth || rate !== lastRate) levelPay = amortPay(bal, rate, remaining);
          if (m === recastMonth) { prePay = months.length ? months[months.length - 1].pay : 0; postPay = levelPay; }
          pay = levelPay;
        } else {
          pay = mode === 'io' ? interest : minPay;
        }
      }
      if (pay > maxPay && m < N) maxPay = pay;
      if (m === N || pay > bal + interest) pay = cents(bal + interest);
      lastRate = rate;
      var deferred = Math.max(0, interest - pay);
      bal = cents(bal + interest - pay);
      if (bal > peak) peak = bal;
      if (m === 1) firstPay = pay;
      deferredTotal += deferred; interestTotal += interest; paidTotal += pay;
      months.push({ m: m, rate: rate, pay: pay, interest: interest, deferred: deferred, bal: bal });
      if (bal <= 0.005) break;
    }
    return { months: months, firstPay: firstPay, recast: recast, reason: reason, recastMonth: recastMonth, prePay: prePay, postPay: postPay,
      peak: peak, deferredTotal: deferredTotal, interestTotal: interestTotal, paidTotal: paidTotal, maxPay: maxPay };
  }

  function raw(id) { return document.getElementById(id).value.trim(); }
  function num(id) { var v = parseFloat(raw(id)); return isNaN(v) ? NaN : v; }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }
  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); });
    body.appendChild(tr);
  }
  function pct(x, d) { return (x * 100).toFixed(d === undefined ? 2 : d) + '%'; }
  function when(m) {
    var y = Math.floor((m - 1) / 12) + 1, mm = (m - 1) % 12 + 1;
    return 'month ' + m + ' (year ' + y + ', month ' + mm + ')';
  }
  function balanceAt(sim, m) { return m <= 0 ? null : (sim.months[Math.min(m, sim.months.length) - 1] || {}).bal; }

  var RESULT_IDS = ['oaMinPay', 'oaRecast', 'oaShock', 'oaPeak', 'oaDeferred', 'oaInterest'];
  function clearResults() {
    RESULT_IDS.forEach(function (id) { set(id, '–'); set(id + 'Note', ''); });
    clearBody('oaOptions'); clearBody('oaCompare'); clearBody('oaSchedule');
  }

  function update() {
    var error = document.getElementById('oaError');
    var amount = num('oaAmount'), term = parseInt(document.getElementById('oaTerm').value, 10), start = num('oaStart'),
        teaser = num('oaTeaser'), fir = num('oaFir'), payCap = num('oaPayCap'),
        negCap = parseFloat(document.getElementById('oaNegCap').value), recastYears = parseInt(document.getElementById('oaRecastYears').value, 10),
        change = raw('oaChange') === '' ? 0 : num('oaChange'), lifeCap = raw('oaLifeCap') === '' ? 100 : num('oaLifeCap');
    var problem = '';
    if (isNaN(amount) || amount <= 0 || amount > 1e8) problem = 'Enter a loan amount above $0.';
    else if (isNaN(start) || start < 0 || start > 30) problem = 'Enter a start rate from 0 to 30%.';
    else if (isNaN(teaser) || teaser < 0 || teaser > 60 || Math.round(teaser) !== teaser) problem = 'Enter 0 to 60 whole months at the start rate.';
    else if (isNaN(fir) || fir < 0 || fir > 30) problem = 'Enter a fully indexed rate from 0 to 30%.';
    else if (isNaN(payCap) || payCap < 0 || payCap > 100) problem = 'Enter a yearly payment cap from 0 to 100%.';
    else if (isNaN(change) || change < -10 || change > 10) problem = 'Enter a yearly rate change from −10 to 10 percentage points.';
    else if (isNaN(lifeCap) || lifeCap < 0 || lifeCap > 100) problem = 'Enter a lifetime rate cap from 0 to 100%.';
    error.hidden = !problem;
    error.textContent = problem;
    if (problem) { clearResults(); return; }

    var o = { amount: amount, term: term, start: start / 100, teaser: teaser, fir: Math.min(fir, lifeCap) / 100, change: change / 100,
      lifeCap: lifeCap / 100, payCap: payCap / 100, negCap: negCap, recastYears: recastYears };
    var sMin = simulate(o, 'min'), sIo = simulate(o, 'io'), sFull = simulate(o, 'full');

    set('oaMinPay', money.format(sMin.firstPay));
    var firstInterestAfter = cents(amount * rateFor(teaser + 1, o) / 12);
    set('oaMinPayNote', 'Based on the ' + start.toFixed(2) + '% start rate. Interest alone is about ' + money.format(firstInterestAfter) + ' a month once the rate is ' + pct(rateFor(teaser + 1, o)) + '.');
    if (sMin.recast) {
      set('oaRecast', 'Year ' + (Math.floor((sMin.recastMonth - 1) / 12) + 1));
      set('oaRecastNote', (sMin.reason === 'cap' ? 'The balance hits the ' + Math.round(negCap * 100) + '% negative-amortization cap in ' : 'Scheduled recast after ' + recastYears + ' years, in ') + when(sMin.recastMonth) + '.');
      var shock = sMin.postPay / sMin.prePay - 1;
      set('oaShock', (shock >= 0 ? '+' : '−') + pct(Math.abs(shock), 0));
      set('oaShockNote', 'The payment changes from ' + money.format(sMin.prePay) + ' to ' + money.format(sMin.postPay) + ' — ' + pct(Math.abs(sMin.postPay / sMin.firstPay - 1), 0) + (sMin.postPay >= sMin.firstPay ? ' above' : ' below') + ' the first payment.');
    } else {
      set('oaRecast', 'None');
      set('oaRecastNote', 'The minimum payment never forces a recast with these inputs.');
      set('oaShock', '–');
      set('oaShockNote', 'No recast.');
    }
    set('oaPeak', money0.format(sMin.peak));
    set('oaPeakNote', pct(sMin.peak / amount, 1) + ' of the original ' + money0.format(amount) + ' loan.');
    set('oaDeferred', money0.format(sMin.deferredTotal));
    set('oaDeferredNote', 'Unpaid interest added to what you owe.');
    set('oaInterest', money0.format(sMin.interestTotal));
    set('oaInterestNote', money0.format(sMin.interestTotal - sFull.interestTotal) + ' more than paying the fully amortizing amount every month.');

    // The four payment choices on the first statement after the start rate ends.
    var mo = Math.min(teaser + 1, term * 12), balNow = mo > 1 ? balanceAt(sMin, mo - 1) : amount, rNow = rateFor(mo, o);
    var minNow = sMin.months[mo - 1] ? sMin.months[mo - 1].pay : sMin.firstPay;
    var intNow = cents(balNow * rNow / 12);
    var ob = clearBody('oaOptions');
    var rem = term * 12 - mo + 1;
    var full30 = amortPay(balNow, rNow, rem), full15 = amortPay(balNow, rNow, Math.min(rem, 180));
    [['Minimum payment', minNow], ['Interest only', intNow], ['Fully amortizing (rest of the ' + term + '-year term)', full30], ['Fully amortizing (15 years)', full15]].forEach(function (row) {
      var effect = row[1] < intNow - 0.005 ? '+' + money.format(intNow - row[1]) + ' added to the balance' : (row[1] - intNow < 0.005 ? 'Balance stays the same' : money.format(row[1] - intNow) + ' off the balance');
      addRow(ob, [row[0], money.format(row[1]), effect]);
    });
    set('oaOptionsMonth', 'Payment choices in month ' + mo + ', at a ' + pct(rNow) + ' rate on a ' + money.format(balNow) + ' balance.');

    var cb = clearBody('oaCompare');
    var yr2 = function (s) { return s.months[12] ? money.format(s.months[12].pay) : '–'; };
    var at = recastYears * 12;
    [['Always pay the minimum', sMin], ['Pay interest only', sIo], ['Pay the fully amortizing amount', sFull]].forEach(function (row) {
      var s = row[1];
      addRow(cb, [row[0], money.format(s.firstPay), yr2(s), money0.format(balanceAt(s, s === sMin && s.recast ? s.recastMonth - 1 : at)), money.format(s.maxPay), money0.format(s.interestTotal), money0.format(s.paidTotal)]);
    });
    set('oaCompareNote', 'Balance column: just before the recast for the minimum-payment path, and after ' + recastYears + ' years for the others.');

    var sb = clearBody('oaSchedule');
    for (var y = 1; y <= term; y++) {
      var slice = sMin.months.slice((y - 1) * 12, y * 12);
      if (!slice.length) break;
      var last = slice[slice.length - 1];
      var paid = 0, intr = 0, def = 0, flag = '';
      slice.forEach(function (x) { paid += x.pay; intr += x.interest; def += x.deferred; if (sMin.recast && x.m === sMin.recastMonth) flag = ' (recast)'; });
      addRow(sb, [y + flag, pct(last.rate), money.format(last.pay), money.format(paid), money.format(intr), money.format(def), money.format(last.bal), pct(last.bal / amount, 1)]);
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('oaForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
